INSERT INTO public."ai_agent_reports" ("id", "session_id", "user_comment", "participating_agents", "conversation_history", "created_at", "resolved", "resolved_at", "resolution_notes") VALUES ('3a14e6af-59fa-4774-8a37-6f9fa8fc38a9', '57podebevdvp3j83zjk5x9', 'No esta siendo de mucha ayuda esta agente. revisarlo', '["Musly Router","Agente Clínico (02-melosmile-agent-medical-history)"]', '[{"role":"assistant","text":"Hola 👋 Soy Musly, tu asistente IA. Puedo agendar citas, consultar la agenda del día, gestionar pacientes y facturación. ¿En qué te ayudo hoy?","intent":"general_query","timestamp":"2026-09-03T12:55:33.995Z"},{"role":"user","text":"telefono de Munir callaos","timestamp":"2026-09-03T12:55:46.838Z"},{"role":"assistant","text":"El sub-agente clínico no puede proporcionar el número de teléfono de Munir Callaos. Su función se limita a datos clínicos. ¿Hay algo sobre el historial médico de Munir Callaos en lo que pueda ayudarte?","intent":"patient_info","timestamp":"2026-09-03T12:55:53.386Z"},{"role":"user","text":"que puedes hacer con ese paciente?","timestamp":"2026-09-03T12:57:50.330Z"},{"role":"assistant","text":"Para poder ayudarte, necesito que me especifiques qué tipo de información necesitas sobre el paciente. ¿Te refieres a su historial clínico, tratamientos, o algún otro dato médico?","intent":"patient_info","timestamp":"2026-09-03T12:57:53.045Z"},{"role":"user","text":"que tratamiento tiene Munir?","timestamp":"2026-09-03T12:58:23.684Z"},{"role":"assistant","text":"Para poder darte información sobre el tratamiento de Munir, necesito que me aclares a qué Munir te refieres. ¿Me puedes proporcionar el nombre completo o algún otro identificador?","intent":"patient_info","timestamp":"2026-09-03T12:58:28.417Z"},{"role":"user","text":"Munir callaos","timestamp":"2026-09-03T12:58:40.510Z"},{"role":"assistant","text":"He consultado al sub-agente clínico sobre el tratamiento de Munir Callaos. El sub-agente clínico me ha respondido que no puede proporcionar información sobre el tratamiento de Munir Callaos. ¿Hay algo más en lo que pueda ayudarte?","intent":"patient_info","timestamp":"2026-09-03T12:58:44.650Z"}]', '2026-09-03T12:59:15.285+00:00', true, '2026-09-03T13:00:46.793+00:00', 'Resuelto: 1) Sub-Agent Clínico migrado de gemini-2.5-flash a gpt-4o-mini, equipada Tool_Search_Patients y habilitada entrega de teléfono/datos de contacto. 2) Endpoints clinical/summary actualizados con resolución flexible por nombre/PAC-###/UUID y datos de contacto completos. 3) Sub-Agent Agendamiento blindado para forzar Tool_List_Appointments en consultas recientes/pasadas/semana pasada.') ON CONFLICT DO NOTHING;
INSERT INTO public."ai_agent_reports" ("id", "session_id", "user_comment", "participating_agents", "conversation_history", "created_at", "resolved", "resolved_at", "resolution_notes") VALUES ('28cbdc68-46b0-45cf-88f8-e5c9f35c7a22', '57podebevdvp3j83zjk5x9', 'este agente deberia tener las tools para ser la mano derecha cuando se le pida algo relacionado con las fichas, consultas, pacientes, agenda entre otras. revisar la ultima configuracion que se le habia realizado hace como 1 semana y comparar comportamiento.', '["Musly Router","Agente Clínico (02-melosmile-agent-medical-history)"]', '[{"role":"assistant","text":"Hola 👋 Soy Musly, tu asistente IA. Puedo agendar citas, consultar la agenda del día, gestionar pacientes y facturación. ¿En qué te ayudo hoy?","intent":"general_query","timestamp":"2026-09-03T12:55:33.995Z"},{"role":"user","text":"telefono de Munir callaos","timestamp":"2026-09-03T12:55:46.838Z"},{"role":"assistant","text":"El sub-agente clínico no puede proporcionar el número de teléfono de Munir Callaos. Su función se limita a datos clínicos. ¿Hay algo sobre el historial médico de Munir Callaos en lo que pueda ayudarte?","intent":"patient_info","timestamp":"2026-09-03T12:55:53.386Z"}]', '2026-09-03T12:57:40.325+00:00', true, '2026-09-03T13:00:46.949+00:00', 'Resuelto: 1) Sub-Agent Clínico migrado de gemini-2.5-flash a gpt-4o-mini, equipada Tool_Search_Patients y habilitada entrega de teléfono/datos de contacto. 2) Endpoints clinical/summary actualizados con resolución flexible por nombre/PAC-###/UUID y datos de contacto completos. 3) Sub-Agent Agendamiento blindado para forzar Tool_List_Appointments en consultas recientes/pasadas/semana pasada.') ON CONFLICT DO NOTHING;
INSERT INTO public."ai_agent_reports" ("id", "session_id", "user_comment", "participating_agents", "conversation_history", "created_at", "resolved", "resolved_at", "resolution_notes") VALUES ('d47c8fd9-0aaf-4531-a825-e86ee79c5248', 'gwu45w4k6kw0r5fquzmcvil', 'no tiene acceso a consultar citas anteriores o no entiende el contexto.', '["Musly Router","Agente de Agendamiento (03-melosmile-agent-appointment)"]', '[{"role":"assistant","text":"Hola 👋 Soy Musly, tu asistente IA. Puedo agendar citas, consultar la agenda del día, gestionar pacientes y facturación. ¿En qué te ayudo hoy?","intent":"general_query","timestamp":"2026-09-03T12:53:04.936Z"},{"role":"user","text":"cuales han sido las citas mas recientes?","timestamp":"2026-09-03T12:53:20.881Z"},{"role":"assistant","text":"No tengo acceso a la información sobre las citas más recientes. Si necesitas detalles sobre citas específicas, por favor proporciona el nombre del paciente o más información.","intent":"schedule_appointment","timestamp":"2026-09-03T12:53:29.874Z"},{"role":"user","text":"la agenda de la semana pasada","timestamp":"2026-09-03T12:54:03.898Z"},{"role":"assistant","text":"No tengo acceso a la agenda de la semana pasada. Si necesitas información sobre citas específicas o deseas agendar, modificar o cancelar una cita, por favor házmelo saber.","intent":"schedule_appointment","timestamp":"2026-09-03T12:54:09.847Z"}]', '2026-09-03T12:54:48.817+00:00', true, '2026-09-03T13:00:47.067+00:00', 'Resuelto: 1) Sub-Agent Clínico migrado de gemini-2.5-flash a gpt-4o-mini, equipada Tool_Search_Patients y habilitada entrega de teléfono/datos de contacto. 2) Endpoints clinical/summary actualizados con resolución flexible por nombre/PAC-###/UUID y datos de contacto completos. 3) Sub-Agent Agendamiento blindado para forzar Tool_List_Appointments en consultas recientes/pasadas/semana pasada.') ON CONFLICT DO NOTHING;
INSERT INTO public."ai_agent_reports" ("id", "session_id", "user_comment", "participating_agents", "conversation_history", "created_at", "resolved", "resolved_at", "resolution_notes") VALUES ('1274e6ee-000b-4fb7-81be-69df5f0bc463', 'ylwm2a8n6mnd31x0wd88v4', 'informacion incorrecta. hay citas para el 8 y 9 de septiembre', '["Musly Router","Agente de Agendamiento (03-melosmile-agent-appointment)"]', '[{"role":"assistant","text":"Hola 👋 Soy Musly, tu asistente IA. Puedo agendar citas, consultar la agenda del día, gestionar pacientes y facturación. ¿En qué te ayudo hoy?","intent":"general_query","timestamp":"2026-09-03T15:28:27.905Z"},{"role":"user","text":"cuales son las proximas citas agendadas?","timestamp":"2026-09-03T15:28:51.303Z"},{"role":"assistant","text":"No hay citas agendadas para la próxima semana. Si necesitas información adicional o deseas agendar una nueva cita, házmelo saber.","intent":"schedule_appointment","timestamp":"2026-09-03T15:28:56.807Z"}]', '2026-09-03T15:29:23.464+00:00', true, '2026-09-08T07:50:49.787+00:00', 'VERIFICADO EN VIVO 08/09/2026: El caso de ''no hay citas'' era correcto en ese momento (BD sin citas). Al crear citas de prueba 8-9 sept, el bot las lista correctamente vía Tool_List_Appointments. Listado E2E en producción: OK.') ON CONFLICT DO NOTHING;
